-- Canonical export recovered read-only from Staging migration history.
-- Version: 20260831070314; name: enterprise_annual_report_view

create or replace view public.enterprise_annual_report with (security_invoker=true) as select e.id as enterprise_id, coalesce(a.period_label,'未設定期間') as period_label, count(a.id)::int as report_ready_assets, count(distinct a.asset_type)::int as asset_types, array_remove(array_agg(distinct s.sdg),null) as sdg_tags, jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'asset_type',a.asset_type,'summary',a.summary,'metric_label',a.metric_label,'metric_value',a.metric_value,'metric_unit',a.metric_unit,'evidence_note',a.evidence_note,'source_type',a.source_type,'source_id',a.source_id) order by a.created_at) as items from public.enterprises e join public.enterprise_esg_assets a on a.enterprise_id=e.id and a.status='approved' and a.report_ready=true left join lateral unnest(a.sdg_tags) s(sdg) on true group by e.id,coalesce(a.period_label,'未設定期間'); grant select on public.enterprise_annual_report to authenticated;
